func deployRoot(t *testing.T) string { t.Helper(); return script.Root(t) }
func write(t *testing.T, path string, data []byte, mode os.FileMode) {
	t.Helper()
	script.Write(t, path, data, mode)
}
func read(t *testing.T, path string) []byte { t.Helper(); return script.Read(t, path) }
func digest(data []byte) string             { sum := sha256.Sum256(data); return hex.EncodeToString(sum[:]) }
func jsonBytes(t *testing.T, v any) []byte {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
func object(t *testing.T, b []byte) map[string]any {
	t.Helper()
	var v map[string]any
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}
func equal(t *testing.T, got, want any) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}
func contains(t *testing.T, got, want string) {
	t.Helper()
	if !strings.Contains(got, want) {
		t.Fatalf("%q does not contain %q", got, want)
	}
}
func absent(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		t.Fatalf("%s exists or could not be inspected: %v", path, err)
	}
}

func successful(t *testing.T, result script.Result) {
	t.Helper()
	if result.Code != 0 {
		t.Fatalf("exit=%d\n%s\n%s", result.Code, result.Stdout, result.Stderr)
	}
}

// TestDeployTool runs native commands as subprocesses with each test's isolated environment.
func TestDeployTool(t *testing.T) {
	i := slices.Index(os.Args, "--")
	if i < 0 {
		return
	}
	args := os.Args[i+1:]
	root, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	code := 2
	if len(args) > 0 {
		switch args[0] {
		case "image":
			var services image.Services
			// Promotion tests aim the real in-binary SDK importer at the
			// stand-in OCI region their parent process serves.
			if endpoint := os.Getenv(ociStandInEnv); endpoint != "" {
				services.ImageImporter = imageimporttest.Importer(endpoint)
			}
			code = image.RunWith(t.Context(), root, args[1:], os.Stdout, os.Stderr, services)
		case "netbird":
			code = client.Run(t.Context(), root, args[1:], os.Stdout, os.Stderr)
		}
	}
	os.Exit(code)
}

func deployTool(t *testing.T) string {
	t.Helper()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "ts-orch")
	write(t, path, []byte("#!/bin/sh\nGOMAXPROCS=2 GORACE=\"${GORACE:+$GORACE }atexit_sleep_ms=0\" exec "+shellQuote(exe)+" -test.run=^TestDeployTool$ -- \"$@\"\n"), 0755)
	return path
}

// runDeploy runs a deploy command. Its subprocesses (the offline builder,
// the promotion tool and this binary re-executed as ts-orch) read only
// repository files under deploy/: the pinned image inputs, systemd and udev
// units and the shell entry points. Tracking that tree alone keeps the
// suite's cached results valid across edits elsewhere; Go records every
// file the test process opens itself.
func runDeploy(t *testing.T, dir string, env map[string]string, name string, args ...string) script.Result {
	t.Helper()
	script.Track(t, "deploy")
	return script.Exec(t, dir, env, name, args...)
}

func runTool(t *testing.T, args ...string) script.Result {
	t.Helper()
	return runDeploy(t, deployRoot(t), nil, deployTool(t), args...)
}

func Root(t testing.TB) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot locate repository test support")
	}
	return filepath.Clean(filepath.Join(filepath.Dir(file), "../../.."))
}

func Write(t testing.TB, path string, data []byte, mode os.FileMode) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
}

func Read(t testing.TB, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func Exec(t *testing.T, dir string, env map[string]string, name string, args ...string) Result {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 3*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = 2 * time.Second
	cmd.Dir = dir
	cmd.Env = os.Environ()
	for key, value := range env {
		prefix := key + "="
		for i := len(cmd.Env) - 1; i >= 0; i-- {
			if strings.HasPrefix(cmd.Env[i], prefix) {
				cmd.Env = append(cmd.Env[:i], cmd.Env[i+1:]...)
			}
		}
		cmd.Env = append(cmd.Env, prefix+value)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if ctx.Err() != nil {
		t.Fatalf("%s exceeded its command deadline: %v", name, ctx.Err())
	}
	code := 0
	if err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok {
			code = exit.ExitCode()
		} else {
			t.Fatalf("start %s: %v", name, err)
		}
	}
	return Result{stdout.String(), stderr.String(), code}
}

func newOffline(t *testing.T) *offlineFixture {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "offline image inputs ")
	f := &offlineFixture{t: t, root: dir, inputs: filepath.Join(dir, "inputs with spaces"), shims: filepath.Join(dir, "tool shims"), guest: t.TempDir(), events: filepath.Join(dir, "events.log"), releaseArgs: filepath.Join(dir, "release-arguments.bin"), metadata: filepath.Join(dir, "fs-metadata.json"), tool: filepath.Join(dir, "release tool"), output: filepath.Join(dir, "candidate image.qcow2"), kernelOutput: filepath.Join(dir, "guest kernel")}
	file := func(name string, b []byte) string {
		path := filepath.Join(f.inputs, name)
		write(t, path, b, 0644)
		return path
	}
	f.base = file("base image.qcow2", []byte("mock qcow2 bytes"))
	f.binary = file("orchestrator binary", []byte("mock verified binary"))
	native := elf("arm64", "mock native verifier")
	native[16] = 3
	f.verifier = file("tb-server-linux-arm64", native)
	netbird := elf("arm64", "mock netbird client")
	netbird[16] = 3
	f.netbird = file("netbird client", netbird)
	f.netbirdConfig = file("netbird config.json", jsonBytes(t, validNetbirdConfig()))
	f.repo = filepath.Join(dir, "repo")
	if err := os.CopyFS(filepath.Join(f.repo, "deploy"), os.DirFS(filepath.Join(deployRoot(t), "deploy"))); err != nil {
		t.Fatal(err)
	}
	inputsPath := filepath.Join(f.repo, "deploy/image/image-inputs.json")
	inputsWire := read(t, inputsPath)
	inputs := object(t, inputsWire)
	pinnedDigest := inputs["netbird"].(map[string]any)["archives"].(map[string]any)["arm64"].(map[string]any)["binary_sha256"].(string)
	write(t, inputsPath, bytes.Replace(inputsWire, []byte(pinnedDigest), []byte(digest(netbird)), 1), 0644)
	f.qualification = file("qualification.json", []byte("mock qualification"))
	f.rootA = file("bootstrap root a.pem", []byte("bootstrap public key a"))
	f.rootB = file("bootstrap root b.pem", []byte("bootstrap public key b"))
	f.timesync = file("timesyncd config.conf", []byte("[Time]\nNTP=ntp.deployment.example\n"))
	f.priority = map[string]string{"--runtime-priority-profile-id": profileID, "--runtime-priority-system-reserve-bytes": "1073741824", "--host-memory-min-bytes": "67108864", "--host-memory-low-bytes": "134217728", "--controller-memory-min-bytes": "67108864", "--controller-memory-low-bytes": "134217728", "--system-slice-memory-min-bytes": "134217728", "--system-slice-memory-low-bytes": "268435456"}
	f.kernel = make([]byte, 64)
	copy(f.kernel[56:], []byte{'A', 'R', 'M', 0x64})
	f.kernel = append(f.kernel, []byte("mock arm64 kernel")...)
	for _, path := range []string{"/etc/systemd/system", "/usr/lib/systemd/system", "/usr/local/lib/terrascale-orchestrator", "/etc/sysusers.d", "/usr/local/bin", "/var/lib", "/srv", "/boot", "/lib/modules/" + offlineKernelRelease, "/usr/bin", "/usr/sbin"} {
		if err := os.MkdirAll(f.path(path), 0755); err != nil {
			t.Fatal(err)
		}
	}
	write(t, f.path(kernelGuest), f.kernel, 0644)
	if err := os.Symlink("vmlinuz-"+offlineKernelRelease, f.path("/boot/vmlinuz")); err != nil {
		t.Fatal(err)
	}
	write(t, f.path("/var/lib/dpkg/status"), []byte("Package: systemd\nStatus: install ok installed\nVersion: 255.4-1ubuntu8.12\n\nPackage: e2fsprogs\nStatus: install ok installed\nVersion: 1.47.0-2.4~exp1ubuntu4.1\n\nPackage: util-linux\nStatus: install ok installed\nVersion: 2.39.3-9ubuntu6.6\n\nPackage: openssh-server\nStatus: install ok installed\nVersion: 1:9.6p1-3ubuntu13.14\n\n"), 0644)
	for _, path := range []string{"/usr/sbin/mkfs.ext4", "/usr/sbin/blkid", "/usr/sbin/wipefs", "/usr/bin/mount"} {
		write(t, f.path(path), []byte("pinned base image volume tool fixture"), 0755)
	}
	for name, data := range map[string]string{"passwd": "root:x:0:0:root:/root:/bin/bash\n", "group": "root:x:0:\n", "shadow": "root:*:0:0:99999:7:::\n", "gshadow": "root:*::\n"} {
		mode := os.FileMode(0644)
		if name == "shadow" || name == "gshadow" {
			mode = 0640
		}
		write(t, f.path("/etc/"+name), []byte(data), mode)
	}
	for _, name := range []string{"systemd-timesyncd.service", "systemd-time-wait-sync.service"} {
		write(t, f.path("/usr/lib/systemd/system/"+name), []byte("[Unit]\nDescription="+name+"\n[Install]\nWantedBy=sysinit.target\n"), 0644)
	}
	write(t, f.path("/usr/lib/systemd/system/ssh.socket"), []byte("[Unit]\nDescription=OpenBSD Secure Shell server socket\n[Install]\nWantedBy=sockets.target\nRequiredBy=ssh.service\n"), 0644)
	for _, directory := range []string{"sockets.target.wants", "ssh.service.requires"} {
		link := f.path("/etc/systemd/system/" + directory + "/ssh.socket")
		if err := os.MkdirAll(filepath.Dir(link), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink("/usr/lib/systemd/system/ssh.socket", link); err != nil {
			t.Fatal(err)
		}
	}
	exe := fakeToolBinary(t)
	for _, kind := range []string{"qemu-img", "guestfish", "systemd-sysusers", "systemctl", "release"} {
		path := filepath.Join(f.shims, kind)
		if kind == "release" {
			path = f.tool
		}
		// These synchronous command fakes start no worker goroutines. Should
		// they run race-instrumented, skip the race runtime's one-second
		// shutdown sleep on each of the builder's hundreds of invocations.
		write(t, path, []byte("#!/bin/sh\nGOMAXPROCS=2 GORACE=\"${GORACE:+$GORACE }atexit_sleep_ms=0\" exec "+shellQuote(exe)+" -test.run=^TestOfflineCommand$ -- "+kind+" \"$@\"\n"), 0755)
	}
	return f
}
func (f *offlineFixture) path(guest string) string {
	return filepath.Join(f.guest, strings.TrimPrefix(guest, "/"))
}
func (f *offlineFixture) run(roots []string, replace, env map[string]string, extra ...string) script.Result {
	options := map[string]string{"--base": f.base, "--kernel-release": offlineKernelRelease, "--binary": f.binary, "--qualification": f.qualification, "--source-revision": offlineSource, "--native-verifier-binary": f.verifier, "--native-verifier-sha256": digest(read(f.t, f.verifier)), "--netbird-binary": f.netbird, "--netbird-sha256": digest(read(f.t, f.netbird)), "--netbird-config": f.netbirdConfig, "--release-tool": f.tool, "--timesyncd-config": f.timesync}
	for k, v := range f.priority {
		options[k] = v
	}
	for k, v := range replace {
		options[k] = v
	}
	var args []string
	for k, v := range options {
		args = append(args, k, v)
	}
	if roots == nil {
		roots = []string{f.rootA, f.rootB}
	}
	for _, root := range roots {
		args = append(args, "--bootstrap-root", root)
	}
	args = append(args, extra...)
	args = append(args, "--out", f.output, "--kernel-out", f.kernelOutput)
	environment := map[string]string{"TS_ORCH_BIN": deployTool(f.t), "PATH": f.shims + string(os.PathListSeparator) + os.Getenv("PATH"), "EVENTS_PATH": f.events, "RELEASE_ARGUMENTS_PATH": f.releaseArgs, "GUESTFISH_SESSION_PATH": filepath.Join(f.root, "guestfish-session"), "BASE_IMAGE_ROOT_PATH": f.guest, "FS_METADATA_PATH": f.metadata, "GUESTFISH_DEAD_MARKER_PATH": filepath.Join(f.root, "guestfish-dead")}
	for k, v := range env {
		environment[k] = v
	}
	return runDeploy(f.t, f.repo, environment, filepath.Join(f.repo, "deploy/image/build-offline.sh"), args...)
}
func (f *offlineFixture) eventText() string {
	b, err := os.ReadFile(f.events)
	if os.IsNotExist(err) {
		return ""
	}
	if err != nil {
		f.t.Fatal(err)
	}
	return string(b)
}
func (f *offlineFixture) noEffects() {
	if strings.Contains(f.eventText(), "guestfish-listen") {
		f.t.Fatal("guestfish launched before input validation")
	}
	absent(f.t, f.output)
	absent(f.t, f.kernelOutput)
}

func (f *offlineFixture) installed(guest string, contents []byte, perm os.FileMode, owner []any) {
	f.t.Helper()
	path := f.path(guest)
	info, err := os.Lstat(path)
	if err != nil {
		f.t.Fatal(err)
	}
	equal(f.t, info.Mode().IsRegular(), true)
	equal(f.t, info.Mode().Perm(), perm)
	equal(f.t, info.Sys().(*syscall.Stat_t).Nlink, uint64(1))
	equal(f.t, read(f.t, path), contents)
	equal(f.t, object(f.t, read(f.t, f.metadata))[guest], owner)
}

func RunWith(ctx context.Context, root string, args []string, stdout, stderr io.Writer, services Services) int {
	if err := ctx.Err(); err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	output := commandio.NewWriter(stdout)
	if len(args) == 0 {
		fmt.Fprintln(stderr, "usage: ts-orch image inputs|build-offline|guestfs|promote")
		return 2
	}
	var e error
	var code int
	switch args[0] {
	case "inputs":
		e, code = runInputs(root, args[1:], output, stderr)
	case "guestfs":
		e, code = runGuestfs(ctx, root, args[1:], output, stderr)
	case "build-offline":
		e, code = runOffline(ctx, root, args[1:], output, stderr)
	case "promote":
		e, code = runPromotion(ctx, root, args[1:], output, stderr, services)
	case "help", "--help", "-h":
		fmt.Fprintln(output, "usage: ts-orch image inputs|build-offline|guestfs|promote")
	default:
		fmt.Fprintln(stderr, "unknown image command:", args[0])
		return 2
	}
	e = errors.Join(e, ctx.Err(), output.Err())
	if e != nil {
		fmt.Fprintf(stderr, "image-%s: %v\n", args[0], e)
		if code == 0 {
			code = 1
		}
	}
	return code
}

func runOffline(ctx context.Context, root string, args []string, out, stderr io.Writer) (error, int) {
	fs := flag.NewFlagSet("build-offline", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		fmt.Fprintln(stderr, "usage: build-offline.sh --base QCOW2 --kernel-release RELEASE --binary FILE --qualification FILE --source-revision SHA --native-verifier-binary FILE --native-verifier-sha256 SHA256 --release-tool FILE --bootstrap-root PEM --timesyncd-config FILE --runtime-priority-profile-id TOKEN --runtime-priority-system-reserve-bytes BYTES --host-memory-min-bytes BYTES --host-memory-low-bytes BYTES --controller-memory-min-bytes BYTES --controller-memory-low-bytes BYTES --system-slice-memory-min-bytes BYTES --system-slice-memory-low-bytes BYTES --out QCOW2 --kernel-out FILE")
	}
	o := OfflineOptions{}
	for _, f := range []struct {
		p    *string
		name string
	}{{&o.Base, "base"}, {&o.KernelRelease, "kernel-release"}, {&o.Binary, "binary"}, {&o.Qualification, "qualification"}, {&o.SourceRevision, "source-revision"}, {&o.NativeVerifier, "native-verifier-binary"}, {&o.NativeSHA256, "native-verifier-sha256"}, {&o.NetBirdBinary, "netbird-binary"}, {&o.NetBirdSHA256, "netbird-sha256"}, {&o.NetBirdConfig, "netbird-config"}, {&o.ReleaseTool, "release-tool"}, {&o.Timesyncd, "timesyncd-config"}, {&o.Out, "out"}, {&o.KernelOut, "kernel-out"}, {&o.Priority.ProfileID, "runtime-priority-profile-id"}} {
		fs.StringVar(f.p, f.name, "", f.name)
	}
	for _, f := range []struct {
		p    *int64
		name string
	}{{&o.Priority.SystemReserve, "runtime-priority-system-reserve-bytes"}, {&o.Priority.HostMin, "host-memory-min-bytes"}, {&o.Priority.HostLow, "host-memory-low-bytes"}, {&o.Priority.ControllerMin, "controller-memory-min-bytes"}, {&o.Priority.ControllerLow, "controller-memory-low-bytes"}, {&o.Priority.SystemMin, "system-slice-memory-min-bytes"}, {&o.Priority.SystemLow, "system-slice-memory-low-bytes"}} {
		fs.Func(f.name, f.name, func(raw string) error {
			if f.name == "runtime-priority-system-reserve-bytes" && !regexp.MustCompile(`^[1-9][0-9]*$`).MatchString(raw) {
				return errors.New("runtime-priority system reserve must be a positive canonical byte count")
			}
			value, err := strconv.ParseInt(raw, 10, 64)
			if err == nil {
				*f.p = value
			}
			return err
		})
	}
	fs.Func("bootstrap-root", "public root PEM", func(v string) error { o.BootstrapRoots = append(o.BootstrapRoots, v); return nil })
	if e := fs.Parse(args); e != nil {
		if errors.Is(e, flag.ErrHelp) {
			return nil, 0
		}
		fs.Usage()
		return e, 2
	}
	if fs.NArg() != 0 {
		fs.Usage()
		return errors.New("unexpected argument"), 2
	}
	if !gitSHA.MatchString(o.SourceRevision) || !kernelRelease.MatchString(o.KernelRelease) {
		return errors.New("invalid source revision or kernel release"), 2
	}
	return OfflineBuild(ctx, root, o, out), 0
}

func OfflineBuild(ctx context.Context, repo string, o OfflineOptions, out io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	for _, required := range []string{o.Base, o.KernelRelease, o.Binary, o.Qualification, o.SourceRevision, o.NativeVerifier, o.NativeSHA256, o.ReleaseTool, o.Timesyncd, o.Out, o.KernelOut} {
		if required == "" {
			return errors.New("missing required build-offline argument")
		}
	}
	if len(o.BootstrapRoots) == 0 || len(o.BootstrapRoots) > bootstrapstart.MaxRootFiles {
		return fmt.Errorf("bootstrap root set must contain at most %d files", bootstrapstart.MaxRootFiles)
	}
	if !gitSHA.MatchString(o.SourceRevision) {
		return errors.New("source revision must be a full lowercase Git SHA-1")
	}
	if !kernelRelease.MatchString(o.KernelRelease) {
		return errors.New("kernel release must be a plain Linux release string")
	}
	if !client.SHA256Pattern.MatchString(o.NativeSHA256) {
		return errors.New("native verifier SHA-256 must be 64 lowercase hex characters")
	}
	if (o.NetBirdBinary != "" || o.NetBirdSHA256 != "") && (o.NetBirdBinary == "" || !client.SHA256Pattern.MatchString(o.NetBirdSHA256)) {
		return errors.New("a supplied NetBird binary needs --netbird-binary and a lowercase --netbird-sha256")
	}
	pin, e := client.LoadPin(filepath.Join(repo, "deploy/image/image-inputs.json"))
	if e != nil {
		return e
	}
	architecture, e := binaryArchitecture(o.Binary)
	if e != nil {
		return e
	}
	archive, e := pin.Archive(architecture)
	if e != nil {
		return e
	}
	if o.NetBirdBinary != "" && o.NetBirdSHA256 != archive.BinarySHA256 {
		return errors.New("supplied NetBird SHA-256 differs from the image pin")
	}

func binaryArchitecture(name string) (string, error) {
	f, err := elf.Open(name)
	if err != nil {
		return "", err
	}
	defer f.Close()
	if f.Class != elf.ELFCLASS64 || f.Data != elf.ELFDATA2LSB || (f.Type != elf.ET_EXEC && f.Type != elf.ET_DYN) {
		return "", errors.New("host binary must be a little-endian ELF64 executable")
	}
	switch f.Machine {
	case elf.EM_AARCH64:
		return "arm64", nil
	case elf.EM_X86_64:
		return "amd64", nil
	}
	return "", errors.New("host binary must target Linux arm64 or amd64")
}

func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

func orderedKeys(raw []byte) ([]string, error) {
	decoder := jsontext.NewDecoder(strings.NewReader(string(raw)))
	first, err := decoder.ReadToken()
	if err != nil || first.Kind() != '{' {
		return nil, errors.New("expected JSON object")
	}
	keys := []string{}
	for decoder.PeekKind() != '}' {
		key, err := decoder.ReadToken()
		if err != nil {
			return nil, err
		}
		keys = append(keys, key.String())
		if _, err = decoder.ReadValue(); err != nil {
			return nil, err
		}
	}
	_, err = decoder.ReadToken()
	return keys, err
}
func ValidatePinJSON(raw []byte) (Pin, error) {
	var pin Pin
	keys, err := orderedKeys(raw)
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"version", "archives", "enrollment_config"}) {
		return pin, errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	if err = json.Unmarshal(raw, &pin, json.RejectUnknownMembers(true)); err != nil {
		return pin, err
	}
	var fields map[string]jsontext.Value
	if err = json.Unmarshal(raw, &fields); err != nil {
		return pin, err
	}
	keys, err = orderedKeys(fields["archives"])
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"arm64", "amd64"}) {
		return pin, errors.New("NetBird archives must pin arm64 and amd64")
	}
	var archives map[string]jsontext.Value
	if err = json.Unmarshal(fields["archives"], &archives); err != nil {
		return pin, err
	}
	for _, arch := range []string{"arm64", "amd64"} {
		keys, err = orderedKeys(archives[arch])
		if err != nil {
			return pin, err
		}
		if !slices.Equal(keys, []string{"url", "bytes", "sha256", "binary_sha256"}) {
			return pin, fmt.Errorf("invalid NetBird %s archive source", arch)
		}
	}
	return pin, ValidatePin(pin)
}

func (p Pin) Archive(architecture string) (Archive, error) {
	switch architecture {
	case "arm64":
		return p.Archives.Arm64, nil
	case "amd64":
		return p.Archives.AMD64, nil
	}
	return Archive{}, errors.New("unsupported architecture")
}
func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}
func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

