func RunWith(ctx context.Context, root string, args []string, stdout, stderr io.Writer, services Services) int {
	if err := ctx.Err(); err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	output := commandio.NewWriter(stdout)
	if len(args) == 0 {
		fmt.Fprintln(stderr, "usage: ts-orch image inputs|build-offline|guestfs|promote")
		return 2
	}
	var e error
	var code int
	switch args[0] {
	case "inputs":
		e, code = runInputs(root, args[1:], output, stderr)
	case "guestfs":
		e, code = runGuestfs(ctx, root, args[1:], output, stderr)
	case "build-offline":
		e, code = runOffline(ctx, root, args[1:], output, stderr)
	case "promote":
		e, code = runPromotion(ctx, root, args[1:], output, stderr, services)
	case "help", "--help", "-h":
		fmt.Fprintln(output, "usage: ts-orch image inputs|build-offline|guestfs|promote")
	default:
		fmt.Fprintln(stderr, "unknown image command:", args[0])
		return 2
	}
	e = errors.Join(e, ctx.Err(), output.Err())
	if e != nil {
		fmt.Fprintf(stderr, "image-%s: %v\n", args[0], e)
		if code == 0 {
			code = 1
		}
	}
	return code
}

func runInputs(root string, args []string, out, stderr io.Writer) (error, int) {
	fs := flag.NewFlagSet("image-inputs", flag.ContinueOnError)
	fs.SetOutput(stderr)
	file := fs.String("file", filepath.Join(root, "deploy/image/image-inputs.json"), "image input manifest")
	qualification := fs.String("qualification", "", "TerraBase or archived image qualification")
	binary := fs.String("binary", "", "archived native verifier binary")
	detail := fs.String("run-detail", "", "Fast run detail")
	command := ""
	for i, a := range args {
		if a == "check" || a == "pin-terrabase" || a == "verify-terrabase-archive" {
			command = a
			args = append(append([]string{}, args[:i]...), args[i+1:]...)
			break
		}
	}
	if e := fs.Parse(args); e != nil {
		if errors.Is(e, flag.ErrHelp) {
			return nil, 0
		}
		return e, 2
	}
	if fs.NArg() != 0 || command == "" {
		return errors.New("usage: ts-orch image inputs [--file MANIFEST] check|pin-terrabase|verify-terrabase-archive"), 2
	}
	manifest, e := LoadInputs(root, *file)
	if e != nil {
		return e, 1
	}
	if command == "check" {
		digest, e := fileHash(*file)
		if e != nil {
			return e, 1
		}
		_, e = fmt.Fprintf(out, "image inputs valid sha256=%s\n", digest)
		return e, 0
	}
	if command == "verify-terrabase-archive" {
		if e := VerifyTerraBaseArchive(manifest.TerraBase, *qualification, *binary); e != nil {
			return e, 1
		}
		_, e := fmt.Fprintln(out, "archived native verifier valid")
		return e, 0
	}
	if *qualification == "" || *detail == "" {
		return errors.New("pin-terrabase requires --qualification and --run-detail"), 2
	}
	architecture, e := manifest.Architecture()
	if e != nil {
		return e, 1
	}
	pin, e := TerraBaseQualification(*qualification, *detail, architecture)
	if e != nil {
		return e, 1
	}
	previous := manifest.TerraBase
	manifest.TerraBase = pin
	b, e := pinManifest(manifest.raw, pin)
	if e != nil {
		return e, 1
	}
	if e = os.WriteFile(*file, b, 0644); e != nil {
		return e, 1
	}
	record, e := canonical(map[string]any{"previous": previous, "pinned": pin})
	if e == nil {
		_, e = out.Write(record)
	}
	return e, 0
}

func (v Inputs) Architecture() (string, error) {
	for _, architecture := range []string{"arm64", "amd64"} {
		if strings.HasSuffix(v.Base.ChecksumName, "-"+architecture+".img") {
			return architecture, nil
		}
	}
	return "", errors.New("base.checksum_name must identify a Linux arm64 or amd64 image")
}

func canonical(v any) ([]byte, error) {
	b, e := json.Marshal(v, jsontext.WithIndent("  "), json.Deterministic(true))
	return append(b, '\n'), e
}
func ValidateTerraBase(p TerraBasePin) error {
	if !gitSHA.MatchString(p.SourceRevision) {
		return errors.New("terrabase.source_revision must be a full SHA")
	}
	if !gitSHA.MatchString(p.SourceTree) {
		return errors.New("terrabase.source_tree must be a full SHA")
	}
	if p.RunID <= 0 || p.RunNumber <= 0 {
		return errors.New("terrabase run identity is invalid")
	}
	if !client.SHA256Pattern.MatchString(p.QualificationSHA256) {
		return errors.New("terrabase.qualification_sha256 must be a SHA-256")
	}
	if !client.SHA256Pattern.MatchString(p.BinarySHA256) {
		return errors.New("terrabase.binary_sha256 must be a SHA-256")
	}
	if p.Archive != nil && (p.Archive.ReleaseTag != "native-verifier-alpha-"+p.BinarySHA256 || !client.SHA256Pattern.MatchString(p.Archive.QualificationSHA256)) {
		return errors.New("native verifier archive needs its digest-named release and pinned image qualification")
	}
	return nil
}

func LoadInputs(root, path string) (Inputs, error) {
	var v Inputs
	b, e := os.ReadFile(path)
	if e != nil {
		return v, e
	}
	if e = json.Unmarshal(b, &v, json.RejectUnknownMembers(true)); e != nil {
		return v, e
	}
	expected, e := canonical(jsontext.Value(b))
	if e != nil {
		return v, e
	}
	if !bytes.Equal(b, expected) {
		return v, errors.New("image-inputs.json is not canonically formatted (json indent 2)")
	}
	var fields map[string]jsontext.Value
	if e = json.Unmarshal(b, &fields); e != nil {
		return v, e
	}
	if e = requireKeys(b, []string{"schema", "region", "base", "trust_roots", "timesyncd_config", "priority", "terrabase", "netbird"}, "image-inputs.json has unexpected or reordered top-level fields"); e != nil {
		return v, e
	}
	for _, item := range []struct {
		key     string
		keys    []string
		message string
	}{{"base", []string{"release_tag", "source_url", "checksum_name", "signer_fingerprint", "oci_image_ocid", "kernel_release", "assets"}, "base has unexpected fields"}, {"priority", []string{"profile_id", "system_reserve_bytes", "host_memory_min_bytes", "host_memory_low_bytes", "controller_memory_min_bytes", "controller_memory_low_bytes", "system_slice_memory_min_bytes", "system_slice_memory_low_bytes"}, "priority has unexpected fields"}, {"terrabase", []string{"source_revision", "source_tree", "run_id", "run_number", "qualification_sha256", "binary_sha256"}, "terrabase has unexpected fields"}} {
		if item.key == "terrabase" && v.TerraBase.Archive != nil {
			item.keys = append(item.keys, "archive")
		}
		if e = requireKeys(fields[item.key], item.keys, item.message); e != nil {
			return v, e
		}
	}
	if _, e = client.ValidatePinJSON(fields["netbird"]); e != nil {
		return v, e
	}
	var roots []jsontext.Value
	if e = json.Unmarshal(fields["trust_roots"], &roots); e != nil {
		return v, e
	}
	var bird map[string]jsontext.Value
	if e = json.Unmarshal(fields["netbird"], &bird); e != nil {
		return v, e
	}
	for _, raw := range append(append([]jsontext.Value{}, roots...), fields["timesyncd_config"], bird["enrollment_config"]) {
		if e = requireKeys(raw, []string{"path", "sha256"}, "checked-in input pins need exactly path and sha256"); e != nil {
			return v, e
		}
	}
	v.raw = jsontext.Value(b).Clone()
	if v.Schema != "terrascale.image.inputs.v2" {
		return v, errors.New("schema must be terrascale.image.inputs.v2")
	}
	if v.Region != "GRU" {
		return v, errors.New("region must be GRU")
	}
	if _, e = v.Architecture(); e != nil {
		return v, e
	}
	base := v.Base
	if !regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$`).MatchString(base.ReleaseTag) {
		return v, errors.New("base.release_tag is invalid")
	}
	if !strings.HasPrefix(base.SourceURL, "https://cloud-images.ubuntu.com/") || !strings.HasSuffix(base.SourceURL, "/"+base.ChecksumName) {
		return v, errors.New("base.source_url must be the Ubuntu image")
	}
	if !regexp.MustCompile(`^[0-9A-F]{40}$`).MatchString(base.SignerFingerprint) {
		return v, errors.New("base.signer_fingerprint is invalid")
	}
	if !strings.HasPrefix(base.OCIImageOCID, "ocid1.image.oc1.sa-saopaulo-1.") {
		return v, errors.New("base OCID must be a GRU image")
	}
	if !kernelRelease.MatchString(base.KernelRelease) {
		return v, errors.New("base.kernel_release is invalid")
	}
	for _, a := range []Asset{base.Assets.Base, base.Assets.Sums, base.Assets.Signature, base.Assets.Keyring} {
		if a.Bytes <= 0 || !client.SHA256Pattern.MatchString(a.SHA256) {
			return v, errors.New("base asset pin is invalid")
		}
	}
	if e = client.ValidatePin(v.NetBird); e != nil {
		return v, e
	}
	entries := append(append([]client.FilePin{}, v.TrustRoots...), v.Timesyncd, v.NetBird.EnrollmentConfig)
	for _, entry := range entries {
		if !client.SHA256Pattern.MatchString(entry.SHA256) {
			return v, errors.New("checked-in input pins need exactly path and sha256")
		}
		path := filepath.Join(root, entry.Path)
		resolved, e := filepath.EvalSymlinks(path)
		if e != nil {
			return v, fmt.Errorf("checked-in input must be a file under deploy/image/inputs: %s", entry.Path)
		}
		allowed := filepath.Join(root, "deploy/image/inputs")
		rel, e := filepath.Rel(allowed, resolved)
		s, se := os.Stat(resolved)
		if e != nil || rel == ".." || strings.HasPrefix(rel, "../") || se != nil || !s.Mode().IsRegular() {
			return v, fmt.Errorf("checked-in input must be a file under deploy/image/inputs: %s", entry.Path)
		}
		d, e := client.SHA256(resolved)
		if e != nil {
			return v, e
		}
		if d != entry.SHA256 {
			return v, fmt.Errorf("checked-in input differs from its pin: %s", entry.Path)
		}
	}
	if _, e = client.ValidateConfig(filepath.Join(root, v.NetBird.EnrollmentConfig.Path)); e != nil {
		return v, e
	}
	if len(v.TrustRoots) < 1 || len(v.TrustRoots) > 16 {
		return v, errors.New("trust_roots must list 1 to 16 roots")
	}
	p := v.Priority
	if !token.MatchString(p.ProfileID) {
		return v, errors.New("priority.profile_id is invalid")
	}
	for _, n := range []int64{p.SystemReserve, p.HostMin, p.HostLow, p.ControllerMin, p.ControllerLow, p.SystemMin, p.SystemLow} {
		if n <= 0 {
			return v, errors.New("priority byte counts must be positive")
		}
	}
	return v, ValidateTerraBase(v.TerraBase)
}

func requireKeys(raw []byte, expected []string, message string) error {
	decoder := jsontext.NewDecoder(bytes.NewReader(raw))
	first, err := decoder.ReadToken()
	if err != nil || first.Kind() != '{' {
		return errors.New(message)
	}
	keys := []string{}
	for decoder.PeekKind() != '}' {
		key, err := decoder.ReadToken()
		if err != nil {
			return err
		}
		keys = append(keys, key.String())
		if _, err = decoder.ReadValue(); err != nil {
			return err
		}
	}
	if _, err = decoder.ReadToken(); err != nil {
		return err
	}
	if !slices.Equal(keys, expected) {
		return errors.New(message)
	}
	return nil
}

func (p Pin) Archive(architecture string) (Archive, error) {
	switch architecture {
	case "arm64":
		return p.Archives.Arm64, nil
	case "amd64":
		return p.Archives.AMD64, nil
	}
	return Archive{}, errors.New("unsupported architecture")
}
func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}
func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

func orderedKeys(raw []byte) ([]string, error) {
	decoder := jsontext.NewDecoder(strings.NewReader(string(raw)))
	first, err := decoder.ReadToken()
	if err != nil || first.Kind() != '{' {
		return nil, errors.New("expected JSON object")
	}
	keys := []string{}
	for decoder.PeekKind() != '}' {
		key, err := decoder.ReadToken()
		if err != nil {
			return nil, err
		}
		keys = append(keys, key.String())
		if _, err = decoder.ReadValue(); err != nil {
			return nil, err
		}
	}
	_, err = decoder.ReadToken()
	return keys, err
}
func ValidatePinJSON(raw []byte) (Pin, error) {
	var pin Pin
	keys, err := orderedKeys(raw)
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"version", "archives", "enrollment_config"}) {
		return pin, errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	if err = json.Unmarshal(raw, &pin, json.RejectUnknownMembers(true)); err != nil {
		return pin, err
	}
	var fields map[string]jsontext.Value
	if err = json.Unmarshal(raw, &fields); err != nil {
		return pin, err
	}
	keys, err = orderedKeys(fields["archives"])
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"arm64", "amd64"}) {
		return pin, errors.New("NetBird archives must pin arm64 and amd64")
	}
	var archives map[string]jsontext.Value
	if err = json.Unmarshal(fields["archives"], &archives); err != nil {
		return pin, err
	}
	for _, arch := range []string{"arm64", "amd64"} {
		keys, err = orderedKeys(archives[arch])
		if err != nil {
			return pin, err
		}
		if !slices.Equal(keys, []string{"url", "bytes", "sha256", "binary_sha256"}) {
			return pin, fmt.Errorf("invalid NetBird %s archive source", arch)
		}
	}
	return pin, ValidatePin(pin)
}

